     1→/**
     2→ * Phone Lines Router
     3→ *
     4→ * Mounts all phone line endpoints
     5→ */
     6→
     7→import { Router } from 'express';
     8→import getPhoneLines from './index.js';
     9→import createPhoneLine from './create.js';
    10→import getPhoneLineById from './getById.js';
    11→import updatePhoneLine from './update.js';
    12→import deletePhoneLine from './delete.js';
    13→import getAssignedUsers from './getAssignedUsers.js';
    14→import assignUsers from './assignUsers.js';
    15→
    16→const router = Router();
    17→
    18→// GET /api/v1/phone-lines - Get all phone lines
    19→router.use('/', getPhoneLines);
    20→
    21→// POST /api/v1/phone-lines - Create new phone line
    22→router.use('/', createPhoneLine);
    23→
    24→// GET /api/v1/phone-lines/:phoneLineId - Get phone line by ID
    25→router.use('/', getPhoneLineById);
    26→
    27→// PATCH /api/v1/phone-lines/:phoneLineId - Update phone line
    28→router.use('/', updatePhoneLine);
    29→
    30→// DELETE /api/v1/phone-lines/:phoneLineId - Delete phone line
    31→router.use('/', deletePhoneLine);
    32→
    33→// GET /api/v1/phone-lines/:phoneLineId/users - Get assigned users
    34→router.use('/', getAssignedUsers);
    35→
    36→// POST /api/v1/phone-lines/:phoneLineId/users - Assign users to phone line
    37→router.use('/', assignUsers);
    38→
    39→export default router;
    40→

