     1→/**
     2→ * POST /api/v1/phone-lines/:phoneLineId/users
     3→ * PUT /api/v1/phone-lines/:phoneLineId/users
     4→ *
     5→ * Assign users to a phone line
     6→ * POST: Add users to existing assignments
     7→ * PUT: Replace all user assignments
     8→ */
     9→
    10→import { Router } from 'express';
    11→import PhoneLineAssignmentService from '../../../services/PhoneLineAssignmentService.js';
    12→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
    13→import { authorizeRole } from '../../../middleware/authorizeRole.js';
    14→import { AppError } from '../../../middleware/errorHandler.js';
    15→
    16→const router = Router();
    17→
    18→/**
    19→ * @route POST /api/v1/phone-lines/:phoneLineId/users
    20→ * @desc Add users to a phone line (appends to existing assignments)
    21→ * @access Admin only
    22→ */
    23→router.post('/:phoneLineId/users', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
    24→  try {
    25→    const { phoneLineId } = req.params;
    26→    const { userIds } = req.body;
    27→
    28→    if (!phoneLineId || isNaN(parseInt(phoneLineId))) {
    29→      throw new AppError('Invalid phone line ID', 400);
    30→    }
    31→
    32→    if (!userIds || !Array.isArray(userIds) || userIds.length === 0) {
    33→      throw new AppError('userIds must be a non-empty array', 400);
    34→    }
    35→
    36→    // Validate all userIds are numbers
    37→    const invalidIds = userIds.filter(id => isNaN(parseInt(id)));
    38→    if (invalidIds.length > 0) {
    39→      throw new AppError('All userIds must be valid numbers', 400);
    40→    }
    41→
    42→    // Assign each user to the phone line
    43→    const results = await Promise.all(
    44→      userIds.map(userId =>
    45→        PhoneLineAssignmentService.assignPhoneLinesToUser(
    46→          parseInt(userId),
    47→          [parseInt(phoneLineId)]
    48→        )
    49→      )
    50→    );
    51→
    52→    res.status(200).json({
    53→      success: true,
    54→      message: `Successfully assigned ${userIds.length} user(s) to phone line`,
    55→      data: {
    56→        assignedCount: userIds.length
    57→      }
    58→    });
    59→  } catch (error) {
    60→    next(error);
    61→  }
    62→});
    63→
    64→/**
    65→ * @route PUT /api/v1/phone-lines/:phoneLineId/users
    66→ * @desc Replace all user assignments for a phone line
    67→ * @access Admin only
    68→ */
    69→router.put('/:phoneLineId/users', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
    70→  try {
    71→    const { phoneLineId } = req.params;
    72→    const { userIds } = req.body;
    73→
    74→    if (!phoneLineId || isNaN(parseInt(phoneLineId))) {
    75→      throw new AppError('Invalid phone line ID', 400);
    76→    }
    77→
    78→    if (!userIds || !Array.isArray(userIds)) {
    79→      throw new AppError('userIds must be an array', 400);
    80→    }
    81→
    82→    // Validate all userIds are numbers
    83→    const invalidIds = userIds.filter(id => isNaN(parseInt(id)));
    84→    if (invalidIds.length > 0) {
    85→      throw new AppError('All userIds must be valid numbers', 400);
    86→    }
    87→
    88→    // Convert userIds to integers
    89→    const integerUserIds = userIds.map(id => parseInt(id));
    90→
    91→    // Replace all user assignments for this phone line
    92→    // This is the CORRECT approach: replace all users of ONE phone line
    93→    const result = await PhoneLineAssignmentService.replacePhoneLineUserAssignments(
    94→      parseInt(phoneLineId),
    95→      integerUserIds
    96→    );
    97→
    98→    res.status(200).json({
    99→      success: true,
   100→      message: result.message,
   101→      data: {
   102→        assignedCount: result.assignedCount
   103→      }
   104→    });
   105→  } catch (error) {
   106→    next(error);
   107→  }
   108→});
   109→
   110→export default router;
   111→

