     1→/**
     2→ * Phone Lines Store (Zustand)
     3→ *
     4→ * State management for WhatsApp phone lines
     5→ */
     6→
     7→import { create } from 'zustand';
     8→import phoneLineService from '../services/phoneLineService';
     9→
    10→const usePhoneLinesStore = create((set, get) => ({
    11→  // State
    12→  phoneLines: [],
    13→  selectedPhoneLine: null,
    14→  loading: false,
    15→  error: null,
    16→  pagination: {
    17→    page: 1,
    18→    limit: 10,
    19→    total: 0,
    20→    totalPages: 0
    21→  },
    22→
    23→  // Actions
    24→
    25→  setPhoneLines: (newPhoneLines) => set({ phoneLines: newPhoneLines }),
    26→
    27→  /**
    28→   * Fetch all phone lines
    29→   */
    30→  fetchPhoneLines: async (params = {}) => {
    31→    set({ loading: true, error: null });
    32→    try {
    33→      const response = await phoneLineService.getPhoneLines(params);
    34→      set({
    35→        phoneLines: response.data || [],
    36→        pagination: response.pagination || {},
    37→        loading: false
    38→      });
    39→    } catch (error) {
    40→      set({
    41→        error: error.message || 'Failed to fetch phone lines',
    42→        loading: false
    43→      });
    44→    }
    45→  },
    46→
    47→  /**
    48→   * Fetch phone lines by WABA ID
    49→   */
    50→  fetchPhoneLinesByWabaId: async (wabaId, activeOnly = true) => {
    51→    set({ loading: true, error: null });
    52→    try {
    53→      const response = await phoneLineService.getPhoneLinesByWabaId(wabaId, activeOnly);
    54→      set({
    55→        phoneLines: response.data || [],
    56→        loading: false
    57→      });
    58→    } catch (error) {
    59→      set({
    60→        error: error.message || 'Failed to fetch WABA phone lines',
    61→        loading: false
    62→      });
    63→    }
    64→  },
    65→
    66→  /**
    67→   * Fetch single phone line by ID
    68→   */
    69→  fetchPhoneLineById: async (phoneLineId) => {
    70→    set({ loading: true, error: null });
    71→    try {
    72→      const response = await phoneLineService.getPhoneLineById(phoneLineId);
    73→      set({
    74→        selectedPhoneLine: response.data,
    75→        loading: false
    76→      });
    77→      return response.data;
    78→    } catch (error) {
    79→      set({
    80→        error: error.message || 'Failed to fetch phone line',
    81→        loading: false
    82→      });
    83→      throw error;
    84→    }
    85→  },
    86→
    87→  /**
    88→   * Create new phone line
    89→   */
    90→  createPhoneLine: async (phoneLineData) => {
    91→    set({ loading: true, error: null });
    92→    try {
    93→      const response = await phoneLineService.createPhoneLine(phoneLineData);
    94→
    95→      // Add new phone line to state
    96→      set(state => ({
    97→        phoneLines: [response.data, ...state.phoneLines],
    98→        loading: false
    99→      }));
   100→
   101→      return response.data;
   102→    } catch (error) {
   103→      set({
   104→        error: error.message || 'Failed to create phone line',
   105→        loading: false
   106→      });
   107→      throw error;
   108→    }
   109→  },
   110→
   111→  /**
   112→   * Update existing phone line
   113→   */
   114→  updatePhoneLine: async (phoneLineId, updateData) => {
   115→    set({ loading: true, error: null });
   116→    try {
   117→      const response = await phoneLineService.updatePhoneLine(phoneLineId, updateData);
   118→
   119→      // Update phone line in state
   120→      set(state => ({
   121→        phoneLines: state.phoneLines.map(phoneLine =>
   122→          phoneLine.id === phoneLineId ? { ...phoneLine, ...response.data } : phoneLine
   123→        ),
   124→        selectedPhoneLine: state.selectedPhoneLine?.id === phoneLineId
   125→          ? { ...state.selectedPhoneLine, ...response.data }
   126→          : state.selectedPhoneLine,
   127→        loading: false
   128→      }));
   129→
   130→      return response.data;
   131→    } catch (error) {
   132→      set({
   133→        error: error.message || 'Failed to update phone line',
   134→        loading: false
   135→      });
   136→      throw error;
   137→    }
   138→  },
   139→
   140→  /**
   141→   * Delete phone line
   142→   */
   143→  deletePhoneLine: async (phoneLineId) => {
   144→    set({ loading: true, error: null });
   145→    try {
   146→      await phoneLineService.deletePhoneLine(phoneLineId);
   147→
   148→      // Remove phone line from state
   149→      set(state => ({
   150→        phoneLines: state.phoneLines.filter(phoneLine => phoneLine.id !== phoneLineId),
   151→        selectedPhoneLine: state.selectedPhoneLine?.id === phoneLineId ? null : state.selectedPhoneLine,
   152→        loading: false
   153→      }));
   154→    } catch (error) {
   155→      set({
   156→        error: error.message || 'Failed to delete phone line',
   157→        loading: false
   158→      });
   159→      throw error;
   160→    }
   161→  },
   162→
   163→  /**
   164→   * Activate phone line
   165→   */
   166→  activatePhoneLine: async (phoneLineId) => {
   167→    set({ loading: true, error: null });
   168→    try {
   169→      const response = await phoneLineService.activatePhoneLine(phoneLineId);
   170→
   171→      // Update phone line in state
   172→      set(state => ({
   173→        phoneLines: state.phoneLines.map(phoneLine =>
   174→          phoneLine.id === phoneLineId ? { ...phoneLine, is_active: true } : phoneLine
   175→        ),
   176→        loading: false
   177→      }));
   178→
   179→      return response.data;
   180→    } catch (error) {
   181→      set({
   182→        error: error.message || 'Failed to activate phone line',
   183→        loading: false
   184→      });
   185→      throw error;
   186→    }
   187→  },
   188→
   189→  /**
   190→   * Deactivate phone line
   191→   */
   192→  deactivatePhoneLine: async (phoneLineId) => {
   193→    set({ loading: true, error: null });
   194→    try {
   195→      const response = await phoneLineService.deactivatePhoneLine(phoneLineId);
   196→
   197→      // Update phone line in state
   198→      set(state => ({
   199→        phoneLines: state.phoneLines.map(phoneLine =>
   200→          phoneLine.id === phoneLineId ? { ...phoneLine, is_active: false } : phoneLine
   201→        ),
   202→        loading: false
   203→      }));
   204→
   205→      return response.data;
   206→    } catch (error) {
   207→      set({
   208→        error: error.message || 'Failed to deactivate phone line',
   209→        loading: false
   210→      });
   211→      throw error;
   212→    }
   213→  },
   214→
   215→  /**
   216→   * Clear error
   217→   */
   218→  clearError: () => set({ error: null }),
   219→
   220→  /**
   221→   * Clear selected phone line
   222→   */
   223→  clearSelectedPhoneLine: () => set({ selectedPhoneLine: null }),
   224→
   225→  /**
   226→   * Reset store
   227→   */
   228→  reset: () => set({
   229→    phoneLines: [],
   230→    selectedPhoneLine: null,
   231→    loading: false,
   232→    error: null,
   233→    pagination: {
   234→      page: 1,
   235→      limit: 10,
   236→      total: 0,
   237→      totalPages: 0
   238→    }
   239→  })
   240→}));
   241→
   242→export default usePhoneLinesStore;
   243→

