     1→/**
     2→ * UserAssignmentSelector Component
     3→ *
     4→ * Component for selecting and displaying assigned users with pills
     5→ */
     6→
     7→import { useState, useEffect } from 'react';
     8→import { Form, Badge, Dropdown } from 'react-bootstrap';
     9→import PropTypes from 'prop-types';
    10→import './UserAssignmentSelector.scss';
    11→import useUsersStore from '../../store/usersStore';
    12→
    13→const UserAssignmentSelector = ({ selectedUserIds = [], onUsersChange }) => {
    14→  const { users, fetchUsers, loading } = useUsersStore();
    15→  const [searchTerm, setSearchTerm] = useState('');
    16→  const [showDropdown, setShowDropdown] = useState(false);
    17→
    18→  useEffect(() => {
    19→    // Fetch only active agents and admins
    20→    fetchUsers({ is_active: true });
    21→  }, [fetchUsers]);
    22→
    23→  // Filter users based on search term and exclude already selected
    24→  const availableUsers = users.filter(user => {
    25→    const matchesSearch = user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    26→                         user.email.toLowerCase().includes(searchTerm.toLowerCase());
    27→    const notSelected = !selectedUserIds.includes(user.id);
    28→    return matchesSearch && notSelected;
    29→  });
    30→
    31→  // Get selected users details
    32→  const selectedUsers = users.filter(user => selectedUserIds.includes(user.id));
    33→
    34→  const handleUserSelect = (userId) => {
    35→    const newSelectedIds = [...selectedUserIds, userId];
    36→    onUsersChange(newSelectedIds);
    37→    setSearchTerm('');
    38→    setShowDropdown(false);
    39→  };
    40→
    41→  const handleUserRemove = (userId) => {
    42→    const newSelectedIds = selectedUserIds.filter(id => id !== userId);
    43→    onUsersChange(newSelectedIds);
    44→  };
    45→
    46→  const getInitials = (name) => {
    47→    return name
    48→      .split(' ')
    49→      .map(word => word[0])
    50→      .join('')
    51→      .toUpperCase()
    52→      .substring(0, 2);
    53→  };
    54→
    55→  const getColorForUser = (userId) => {
    56→    const colors = ['primary', 'success', 'info', 'warning', 'secondary'];
    57→    return colors[userId % colors.length];
    58→  };
    59→
    60→  return (
    61→    <div className="user-assignment-selector">
    62→      <Form.Group className="mb-3">
    63→        <Form.Label>Asignar usuarios</Form.Label>
    64→
    65→        {/* Selected Users Pills */}
    66→        <div className="selected-users mb-2">
    67→          {selectedUsers.map(user => (
    68→            <Badge
    69→              key={user.id}
    70→              bg={getColorForUser(user.id)}
    71→              className="user-pill me-2 mb-2"
    72→            >
    73→              <span className="user-initials me-1">
    74→                {getInitials(user.name)}
    75→              </span>
    76→              <span className="user-name">{user.name}</span>
    77→              <button
    78→                type="button"
    79→                className="btn-remove-user"
    80→                onClick={() => handleUserRemove(user.id)}
    81→                aria-label={`Remover ${user.name}`}
    82→              >
    83→                ×
    84→              </button>
    85→            </Badge>
    86→          ))}
    87→        </div>
    88→
    89→        {/* Search Input */}
    90→        <Dropdown
    91→          show={showDropdown}
    92→          onToggle={(isOpen) => setShowDropdown(isOpen)}
    93→        >
    94→          <Form.Control
    95→            type="text"
    96→            placeholder="Buscar usuarios para asignar..."
    97→            value={searchTerm}
    98→            onChange={(e) => {
    99→              setSearchTerm(e.target.value);
   100→              setShowDropdown(true);
   101→            }}
   102→            onFocus={() => setShowDropdown(true)}
   103→            disabled={loading}
   104→          />
   105→
   106→          {showDropdown && availableUsers.length > 0 && (
   107→            <Dropdown.Menu show className="w-100">
   108→              {availableUsers.map(user => (
   109→                <Dropdown.Item
   110→                  key={user.id}
   111→                  onClick={() => handleUserSelect(user.id)}
   112→                >
   113→                  <div className="d-flex align-items-center">
   114→                    <Badge
   115→                      bg={getColorForUser(user.id)}
   116→                      className="user-initials-badge me-2"
   117→                    >
   118→                      {getInitials(user.name)}
   119→                    </Badge>
   120→                    <div>
   121→                      <div className="fw-bold">{user.name}</div>
   122→                      <small className="text-muted">{user.email}</small>
   123→                    </div>
   124→                  </div>
   125→                </Dropdown.Item>
   126→              ))}
   127→            </Dropdown.Menu>
   128→          )}
   129→
   130→          {showDropdown && searchTerm && availableUsers.length === 0 && (
   131→            <Dropdown.Menu show className="w-100">
   132→              <Dropdown.Item disabled>
   133→                No se encontraron usuarios
   134→              </Dropdown.Item>
   135→            </Dropdown.Menu>
   136→          )}
   137→        </Dropdown>
   138→
   139→        <Form.Text className="text-muted">
   140→          {selectedUsers.length === 0
   141→            ? 'No hay usuarios asignados'
   142→            : `${selectedUsers.length} usuario(s) asignado(s)`}
   143→        </Form.Text>
   144→      </Form.Group>
   145→    </div>
   146→  );
   147→};
   148→
   149→UserAssignmentSelector.propTypes = {
   150→  selectedUserIds: PropTypes.arrayOf(PropTypes.number),
   151→  onUsersChange: PropTypes.func.isRequired
   152→};
   153→
   154→UserAssignmentSelector.defaultProps = {
   155→  selectedUserIds: []
   156→};
   157→
   158→export default UserAssignmentSelector;
   159→

