     1→/**
     2→ * Phone Line Assignment Service
     3→ *
     4→ * Handles assignment of Phone Lines to agent users
     5→ * Uses Sequelize ORM for database operations
     6→ */
     7→
     8→import { User, PhoneLine, PhoneLineUserAssignment, Role, WhatsAppLine, LineUserAssignment } from '../models/sequelize/associations.js';
     9→import sequelize from '../config/sequelize.js';
    10→import { AppError } from '../middleware/errorHandler.js';
    11→
    12→class PhoneLineAssignmentService {
    13→  /**
    14→   * Assign phone lines to a user (agent or admin)
    15→   * Uses transaction to ensure atomicity
    16→   *
    17→   * @param {number} userId - User ID
    18→   * @param {number[]} phoneLineIds - Array of phone line IDs to assign
    19→   * @returns {Promise<Object>} Assignment result
    20→   */
    21→  async assignPhoneLinesToUser(userId, phoneLineIds) {
    22→    const transaction = await sequelize.transaction();
    23→
    24→    try {
    25→      // Validate user exists and is an agent or admin
    26→      const user = await User.findByPk(userId, {
    27→        include: [{
    28→          model: Role,
    29→          as: 'role',
    30→          attributes: ['role_name']
    31→        }],
    32→        transaction
    33→      });
    34→
    35→      if (!user) {
    36→        throw new AppError('User not found', 404);
    37→      }
    38→
    39→      if (!['agent', 'admin', 'manager'].includes(user.role.role_name)) {
    40→        throw new AppError('Only agents, admins and managers can be assigned phone lines', 400);
    41→      }
    42→
    43→      if (!user.is_active) {
    44→        throw new AppError('Cannot assign phone lines to inactive user', 400);
    45→      }
    46→
    47→      // Validate all phone lines exist and are active
    48→      const phoneLines = await PhoneLine.findAll({
    49→        where: { id: phoneLineIds },
    50→        attributes: ['id', 'is_active', 'phone_number'],
    51→        transaction
    52→      });
    53→
    54→      if (phoneLines.length !== phoneLineIds.length) {
    55→        throw new AppError('One or more phone lines not found', 404);
    56→      }
    57→
    58→      const inactiveLines = phoneLines.filter(line => !line.is_active);
    59→      if (inactiveLines.length > 0) {
    60→        throw new AppError('Cannot assign inactive phone lines', 400);
    61→      }
    62→
    63→      // Create assignments (ignore duplicates)
    64→      const assignments = phoneLineIds.map(phoneLineId => ({
    65→        user_id: userId,
    66→        phone_line_id: phoneLineId
    67→      }));
    68→
    69→      await PhoneLineUserAssignment.bulkCreate(assignments, {
    70→        ignoreDuplicates: true,
    71→        transaction
    72→      });
    73→
    74→      // Also assign to WhatsAppLine if exists (for legacy compatibility)
    75→      const phoneNumbers = phoneLines.map(line => line.phone_number);
    76→      const whatsappLines = await WhatsAppLine.findAll({
    77→        where: { phone_number: phoneNumbers, is_active: true },
    78→        attributes: ['id', 'phone_number'],
    79→        transaction
    80→      });
    81→
    82→      if (whatsappLines.length > 0) {
    83→        const whatsappAssignments = whatsappLines.map(line => ({
    84→          user_id: userId,
    85→          line_id: line.id
    86→        }));
    87→
    88→        await LineUserAssignment.bulkCreate(whatsappAssignments, {
    89→          ignoreDuplicates: true,
    90→          transaction
    91→        });
    92→      }
    93→
    94→      await transaction.commit();
    95→
    96→      return {
    97→        success: true,
    98→        message: `Successfully assigned ${phoneLineIds.length} phone line(s) to user`,
    99→        assignedCount: phoneLineIds.length
   100→      };
   101→    } catch (error) {
   102→      await transaction.rollback();
   103→
   104→      if (error instanceof AppError) throw error;
   105→      console.error('Assign phone lines to user error:', error);
   106→      throw new AppError('Failed to assign phone lines to user', 500);
   107→    }
   108→  }
   109→
   110→  /**
   111→   * Remove phone line assignment from user
   112→   *
   113→   * @param {number} userId - User ID
   114→   * @param {number} phoneLineId - Phone Line ID to remove
   115→   * @returns {Promise<Object>} Removal result
   116→   */
   117→  async removePhoneLineFromUser(userId, phoneLineId) {
   118→    const transaction = await sequelize.transaction();
   119→    
   120→    try {
   121→      // Get phone line to find matching WhatsAppLine
   122→      const phoneLine = await PhoneLine.findByPk(phoneLineId, {
   123→        attributes: ['phone_number'],
   124→        transaction
   125→      });
   126→
   127→      if (!phoneLine) {
   128→        throw new AppError('Phone line not found', 404);
   129→      }
   130→
   131→      // Remove PhoneLine assignment
   132→      const deleted = await PhoneLineUserAssignment.destroy({
   133→        where: {
   134→          user_id: userId,
   135→          phone_line_id: phoneLineId
   136→        },
   137→        transaction
   138→      });
   139→
   140→      if (deleted === 0) {
   141→        throw new AppError('Phone line assignment not found', 404);
   142→      }
   143→
   144→      // Also remove WhatsAppLine assignment if exists (for legacy compatibility)
   145→      const whatsappLine = await WhatsAppLine.findOne({
   146→        where: { phone_number: phoneLine.phone_number, is_active: true },
   147→        attributes: ['id'],
   148→        transaction
   149→      });
   150→
   151→      if (whatsappLine) {
   152→        await LineUserAssignment.destroy({
   153→          where: {
   154→            user_id: userId,
   155→            line_id: whatsappLine.id
   156→          },
   157→          transaction
   158→        });
   159→      }
   160→
   161→      await transaction.commit();
   162→
   163→      return {
   164→        success: true,
   165→        message: 'Phone line assignment removed successfully'
   166→      };
   167→    } catch (error) {
   168→      await transaction.rollback();
   169→      
   170→      if (error instanceof AppError) throw error;
   171→      console.error('Remove phone line from user error:', error);
   172→      throw new AppError('Failed to remove phone line assignment', 500);
   173→    }
   174→  }
   175→
   176→  /**
   177→   * Get all phone lines assigned to a user
   178→   *
   179→   * @param {number} userId - User ID
   180→   * @returns {Promise<Array>} Assigned phone lines
   181→   */
   182→  async getUserAssignedPhoneLines(userId) {
   183→    try {
   184→      const user = await User.findByPk(userId, {
   185→        include: [
   186→          {
   187→            model: PhoneLine,
   188→            as: 'assignedPhoneLines',
   189→            attributes: [
   190→              'id',
   191→              'name',
   192→              'phone_number',
   193→              'display_phone_number',
   194→              'verified_name',
   195→              'waba_id',
   196→              'quality_rating',
   197→              'is_active'
   198→            ],
   199→            through: {
   200→              attributes: ['assigned_at']
   201→            }
   202→          }
   203→        ]
   204→      });
   205→
   206→      if (!user) {
   207→        throw new AppError('User not found', 404);
   208→      }
   209→
   210→      return user.assignedPhoneLines.map(line => ({
   211→        id: line.id,
   212→        name: line.name,
   213→        phone_number: line.phone_number,
   214→        display_phone_number: line.display_phone_number,
   215→        verified_name: line.verified_name,
   216→        waba_id: line.waba_id,
   217→        quality_rating: line.quality_rating,
   218→        is_active: line.is_active,
   219→        assigned_at: line.PhoneLineUserAssignment.assigned_at
   220→      }));
   221→    } catch (error) {
   222→      if (error instanceof AppError) throw error;
   223→      console.error('Get user assigned phone lines error:', error);
   224→      throw new AppError('Failed to get assigned phone lines', 500);
   225→    }
   226→  }
   227→
   228→  /**
   229→   * Get all users assigned to a phone line
   230→   *
   231→   * @param {number} phoneLineId - Phone Line ID
   232→   * @returns {Promise<Array>} Assigned users
   233→   */
   234→  async getPhoneLineAssignedUsers(phoneLineId) {
   235→    try {
   236→      const phoneLine = await PhoneLine.findByPk(phoneLineId, {
   237→        include: [
   238→          {
   239→            model: User,
   240→            as: 'assignedUsers',
   241→            attributes: ['id', 'name', 'email', 'is_active'],
   242→            through: {
   243→              attributes: ['assigned_at']
   244→            }
   245→          }
   246→        ]
   247→      });
   248→
   249→      if (!phoneLine) {
   250→        throw new AppError('Phone line not found', 404);
   251→      }
   252→
   253→      return phoneLine.assignedUsers.map(user => ({
   254→        id: user.id,
   255→        name: user.name,
   256→        email: user.email,
   257→        is_active: user.is_active,
   258→        assigned_at: user.PhoneLineUserAssignment.assigned_at
   259→      }));
   260→    } catch (error) {
   261→      if (error instanceof AppError) throw error;
   262→      console.error('Get phone line assigned users error:', error);
   263→      throw new AppError('Failed to get assigned users', 500);
   264→    }
   265→  }
   266→
   267→  /**
   268→   * Replace all phone line assignments for a user (bulk update)
   269→   *
   270→   * @param {number} userId - User ID
   271→   * @param {number[]} phoneLineIds - New array of phone line IDs
   272→   * @returns {Promise<Object>} Update result
   273→   */
   274→  async replaceUserPhoneLineAssignments(userId, phoneLineIds) {
   275→    const transaction = await sequelize.transaction();
   276→
   277→    try {
   278→      // Validate user exists and is an agent or admin
   279→      const user = await User.findByPk(userId, {
   280→        include: [{
   281→          model: Role,
   282→          as: 'role',
   283→          attributes: ['role_name']
   284→        }],
   285→        transaction
   286→      });
   287→
   288→      if (!user) {
   289→        throw new AppError('User not found', 404);
   290→      }
   291→
   292→      if (!['agent', 'admin', 'manager'].includes(user.role.role_name)) {
   293→        throw new AppError('Only agents, admins and managers can be assigned phone lines', 400);
   294→      }
   295→
   296→      // Remove all existing assignments
   297→      await PhoneLineUserAssignment.destroy({
   298→        where: { user_id: userId },
   299→        transaction
   300→      });
   301→
   302→      // Also remove WhatsAppLine assignments (for legacy compatibility)
   303→      await LineUserAssignment.destroy({
   304→        where: { user_id: userId },
   305→        transaction
   306→      });
   307→
   308→      // Add new assignments if any
   309→      if (phoneLineIds && phoneLineIds.length > 0) {
   310→        // Validate all phone lines exist and are active
   311→        const phoneLines = await PhoneLine.findAll({
   312→          where: { id: phoneLineIds },
   313→          attributes: ['id', 'is_active', 'phone_number'],
   314→          transaction
   315→        });
   316→
   317→        if (phoneLines.length !== phoneLineIds.length) {
   318→          throw new AppError('One or more phone lines not found', 404);
   319→        }
   320→
   321→        const inactiveLines = phoneLines.filter(line => !line.is_active);
   322→        if (inactiveLines.length > 0) {
   323→          throw new AppError('Cannot assign inactive phone lines', 400);
   324→        }
   325→
   326→        const assignments = phoneLineIds.map(phoneLineId => ({
   327→          user_id: userId,
   328→          phone_line_id: phoneLineId
   329→        }));
   330→
   331→        await PhoneLineUserAssignment.bulkCreate(assignments, {
   332→          transaction
   333→        });
   334→
   335→        // Also assign to WhatsAppLine if exists (for legacy compatibility)
   336→        const phoneNumbers = phoneLines.map(line => line.phone_number);
   337→        const whatsappLines = await WhatsAppLine.findAll({
   338→          where: { phone_number: phoneNumbers, is_active: true },
   339→          attributes: ['id', 'phone_number'],
   340→          transaction
   341→        });
   342→
   343→        if (whatsappLines.length > 0) {
   344→          const whatsappAssignments = whatsappLines.map(line => ({
   345→            user_id: userId,
   346→            line_id: line.id
   347→          }));
   348→
   349→          await LineUserAssignment.bulkCreate(whatsappAssignments, {
   350→            transaction
   351→          });
   352→        }
   353→      }
   354→
   355→      await transaction.commit();
   356→
   357→      return {
   358→        success: true,
   359→        message: 'Phone line assignments updated successfully',
   360→        assignedCount: phoneLineIds ? phoneLineIds.length : 0
   361→      };
   362→    } catch (error) {
   363→      await transaction.rollback();
   364→
   365→      if (error instanceof AppError) throw error;
   366→      console.error('Replace user phone line assignments error:', error);
   367→      throw new AppError('Failed to update phone line assignments', 500);
   368→    }
   369→  }
   370→
   371→  /**
   372→   * Replace all user assignments for a phone line (bulk update)
   373→   * This replaces ALL users assigned to a specific phone line
   374→   *
   375→   * @param {number} phoneLineId - Phone Line ID
   376→   * @param {number[]} userIds - New array of user IDs to assign
   377→   * @returns {Promise<Object>} Update result
   378→   */
   379→  async replacePhoneLineUserAssignments(phoneLineId, userIds) {
   380→    const transaction = await sequelize.transaction();
   381→
   382→    try {
   383→      // Validate phone line exists and is active
   384→      const phoneLine = await PhoneLine.findByPk(phoneLineId, { attributes: ['id', 'is_active', 'phone_number'], transaction });
   385→
   386→      if (!phoneLine) {
   387→        throw new AppError('Phone line not found', 404);
   388→      }
   389→
   390→      if (!phoneLine.is_active) {
   391→        throw new AppError('Cannot assign users to inactive phone line', 400);
   392→      }
   393→
   394→      // Remove all existing user assignments for this phone line
   395→      await PhoneLineUserAssignment.destroy({
   396→        where: { phone_line_id: phoneLineId },
   397→        transaction
   398→      });
   399→
   400→      // Also remove WhatsAppLine user assignments (for legacy compatibility)
   401→      const whatsappLine = await WhatsAppLine.findOne({
   402→        where: { phone_number: phoneLine.phone_number, is_active: true },
   403→        attributes: ['id'],
   404→        transaction
   405→      });
   406→
   407→      if (whatsappLine) {
   408→        await LineUserAssignment.destroy({
   409→          where: { line_id: whatsappLine.id },
   410→          transaction
   411→        });
   412→      }
   413→
   414→      // Add new user assignments if any
   415→      if (userIds && userIds.length > 0) {
   416→        // Validate all users exist and are agents or admins
   417→        const users = await User.findAll({
   418→          where: { id: userIds },
   419→          include: [{
   420→            model: Role,
   421→            as: 'role',
   422→            attributes: ['role_name']
   423→          }],
   424→          transaction
   425→        });
   426→
   427→        if (users.length !== userIds.length) {
   428→          throw new AppError('One or more users not found', 404);
   429→        }
   430→
   431→        // Validate all users are agents, admins or managers and active
   432→        const invalidUsers = users.filter(user =>
   433→          !['agent', 'admin', 'manager'].includes(user.role.role_name) || !user.is_active
   434→        );
   435→
   436→        if (invalidUsers.length > 0) {
   437→          throw new AppError('All users must be active agents, admins or managers', 400);
   438→        }
   439→
   440→        // Create new assignments
   441→        const assignments = userIds.map(userId => ({
   442→          user_id: userId,
   443→          phone_line_id: phoneLineId
   444→        }));
   445→
   446→        await PhoneLineUserAssignment.bulkCreate(assignments, {
   447→          transaction
   448→        });
   449→
   450→        // Also assign users to WhatsAppLine if exists (for legacy compatibility)
   451→        if (whatsappLine) {
   452→          const whatsappAssignments = userIds.map(userId => ({
   453→            user_id: userId,
   454→            line_id: whatsappLine.id
   455→          }));
   456→
   457→          await LineUserAssignment.bulkCreate(whatsappAssignments, {
   458→            transaction
   459→          });
   460→        }
   461→      }
   462→
   463→      await transaction.commit();
   464→
   465→      return {
   466→        success: true,
   467→        message: 'Phone line user assignments updated successfully',
   468→        assignedCount: userIds ? userIds.length : 0
   469→      };
   470→    } catch (error) {
   471→      await transaction.rollback();
   472→
   473→      if (error instanceof AppError) throw error;
   474→      console.error('Replace phone line user assignments error:', error);
   475→      throw new AppError('Failed to update phone line user assignments', 500);
   476→    }
   477→  }
   478→
   479→  /**
   480→   * Get all active phone lines (for admins)
   481→   *
   482→   * @returns {Promise<Array>} All active phone lines
   483→   */
   484→  async getAllActivePhoneLines() {
   485→    try {
   486→      const phoneLines = await PhoneLine.findAll({
   487→        where: { is_active: true },
   488→        attributes: [
   489→          'id',
   490→          'name',
   491→          'phone_number',
   492→          'display_phone_number',
   493→          'verified_name',
   494→          'waba_id',
   495→          'quality_rating',
   496→          'is_active'
   497→        ],
   498→        order: [['name', 'ASC']]
   499→      });
   500→
   501→      return phoneLines.map(line => line.toJSON());
   502→    } catch (error) {
   503→      console.error('Get all active phone lines error:', error);
   504→      throw new AppError('Failed to get active phone lines', 500);
   505→    }
   506→  }
   507→}
   508→
   509→export default new PhoneLineAssignmentService();
