    13→class UserService {
    14→  /**
    15→   * Get all users with pagination and filters
    16→   * OPTIMIZED: Eager loading for Role and assigned PhoneLines (eliminates N+1 queries)
    17→   */
    18→  async getAll({ page = 1, limit = 20, role, isActive } = {}) {
    19→    try {
    20→      const offset = (page - 1) * limit;
    21→      const where = {};
    22→      const includeWhere = {};
    23→
    24→      if (isActive !== undefined) where.is_active = isActive;
    25→      if (role) includeWhere.role_name = role;
    26→
    27→      const { count, rows: users } = await User.findAndCountAll({
    28→        where,
    29→        include: [
    30→          {
    31→            model: Role,
    32→            as: 'role',
    33→            attributes: ['id', 'role_name'],
    34→            where: Object.keys(includeWhere).length > 0 ? includeWhere : undefined,
    35→            required: Object.keys(includeWhere).length > 0
    36→          },
    37→          {
    38→            model: PhoneLine,
    39→            as: 'assignedPhoneLines',
    40→            attributes: ['id'],
    41→            through: { attributes: [] },
    42→            required: false
    43→          }
    44→        ],
    45→        attributes: ['id', 'email', 'name', 'phone_number', 'is_active', 'role_id', 'created_at', 'updated_at'],
    46→        limit,
    47→        offset,
    48→        order: [['created_at', 'DESC']],
    49→        distinct: true,
    50→        subQuery: false
    51→      });
    52→
    53→      const usersWithLines = users.map((user) => {
