    57→        return userJson;
    58→      });
    59→
    60→      return {
    61→        users: usersWithLines,
    62→        total: count,
    63→        page,
    64→        totalPages: Math.ceil(count / limit)
    65→      };
    66→    } catch (error) {
    67→      console.error('Get users error:', error);
    68→      throw error;
    69→    }
    70→  }
    71→
    72→  async getById(userId) {
    73→    try {
    74→      const user = await User.findByPk(userId, {
    75→        include: [
    76→          {
    77→            model: Role,
    78→            as: 'role',
    79→            attributes: ['id', 'role_name']
    80→          },
    81→          {
    82→            model: PhoneLine,
    83→            as: 'assignedPhoneLines',
