   105→  async create({ email, password, name, phoneNumber, role }) {
   106→    try {
   107→      if (!['admin', 'agent', 'manager'].includes(role)) {
   108→        throw new Error('Invalid role');
   109→      }
   110→
   111→      const roleRecord = await Role.findOne({
   112→        where: { role_name: role },
   113→        attributes: ['id']
   114→      });
   115→
   116→      if (!roleRecord) throw new Error('Role not found');
   117→
   118→      const existingUser = await User.findOne({
   119→        where: { email },
   120→        attributes: ['id']
   121→      });
   122→
   123→      if (existingUser) throw new Error('Email already exists');
   124→
   125→      const passwordHash = await bcrypt.hash(password, 12);
   126→      const newUser = await User.create({
   127→        role_id: roleRecord.id,
   128→        email,
   129→        password_hash: passwordHash,
   130→        name,
   131→        phone_number: phoneNumber || null,
   132→        is_active: true
   133→      });
   134→
   135→      return await this.getById(newUser.id);
   136→    } catch (error) {
   137→      console.error('Create user error:', error);
   138→      throw error;
   139→    }
   140→  }
   141→
   142→  async update(userId, updates) {
   143→    try {
   144→      const user = await User.findByPk(userId);
   145→      if (!user) throw new Error('User not found');
   146→
   147→      const allowedFields = ['name', 'phone_number', 'phoneNumber', 'is_active', 'password'];
   148→      const updateData = {};
   149→
   150→      for (const [key, value] of Object.entries(updates)) {
   151→        if (allowedFields.includes(key)) {
   152→          if (key === 'password') {
   153→            updateData.password_hash = await bcrypt.hash(value, 12);
   154→          } else if (key === 'phone_number' || key === 'phoneNumber') {
   155→            updateData.phone_number = value || null;
   156→          } else {
   157→            updateData[key] = value;
   158→          }
   159→        }
   160→      }
   161→
   162→      if (Object.keys(updateData).length === 0) {
   163→        throw new Error('No valid fields to update');
   164→      }
   165→
   166→      await user.update(updateData);
   167→      return await this.getById(userId);
   168→    } catch (error) {
   169→      console.error('Update user error:', error);
   170→      throw error;
   171→    }
   172→  }
   173→
   174→  async delete(userId) {
   175→    try {
   176→      const user = await User.findByPk(userId);
   177→      if (!user) throw new Error('User not found');
   178→
   179→      // Soft delete: mark as inactive instead of hard delete
   180→      // This allows us to provide better error messages on login
   181→      // and maintain data integrity for historical records
