   197→            through: {
   198→              attributes: ['assigned_at']
   199→            }
   200→          }
   201→        ]
   202→      });
   203→
   204→      if (!user) throw new Error('User not found');
   205→
   206→      return user.assignedLines.map(line => ({
   207→        id: line.id,
   208→        company_name: line.company_name,
   209→        phone_number: line.phone_number,
