   219→  async assignLines(userId, lineIds) {
   220→    const transaction = await sequelize.transaction();
   221→    try {
   222→      const user = await User.findByPk(userId, {
   223→        include: [{
   224→          model: Role,
   225→          as: 'role',
   226→          attributes: ['role_name']
   227→        }],
   228→        transaction
   229→      });
   230→
   231→      if (!user) throw new Error('User not found');
   232→      if (!['agent', 'manager', 'admin'].includes(user.role.role_name)) {
