     5→/**
     6→ * User Model (Sequelize ORM)
     7→ *
     8→ * Represents platform users (admins and agents) with authentication and authorization.
     9→ * Phase F: Added password hashing hooks (beforeCreate, beforeUpdate)
    10→ */
    11→const User = sequelize.define('User', {
    12→  id: {
    13→    type: DataTypes.INTEGER,
    14→    primaryKey: true,
    15→    autoIncrement: true,
    16→  },
    17→  role_id: {
    18→    type: DataTypes.INTEGER,
    19→    allowNull: false,
    20→    references: {
    21→      model: 'roles',
    22→      key: 'id',
    23→    },
    24→    validate: {
    25→      notNull: {
    26→        msg: 'Role ID is required',
    27→      },
    28→      async isValidRole(value) {
    29→        const { default: Role } = await import('./Role.js');
    30→        const role = await Role.findByPk(value);
    31→        if (!role) {
    32→          throw new Error('Invalid role ID');
    33→        }
    34→      },
    35→    },
    36→  },
    37→  email: {
    38→    type: DataTypes.STRING(255),
    39→    allowNull: false,
    40→    unique: {
    41→      msg: 'Email address already in use',
    42→    },
    43→    validate: {
    44→      isEmail: {
    45→        msg: 'Must be a valid email address',
    46→      },
    47→      notNull: {
    48→        msg: 'Email is required',
    49→      },
    50→      notEmpty: {
    51→        msg: 'Email cannot be empty',
    52→      },
    53→    },
    54→  },
    55→  password_hash: {
    56→    type: DataTypes.STRING(255),
    57→    allowNull: false,
    58→    validate: {
    59→      notNull: {
    60→        msg: 'Password hash is required',
    61→      },
    62→      notEmpty: {
    63→        msg: 'Password hash cannot be empty',
    64→      },
    65→    },
    66→  },
    67→  password: {
    68→    type: DataTypes.VIRTUAL,
    69→    allowNull: true,
    70→    validate: {
    71→      len: {
    72→        args: [8, 255],
    73→        msg: 'Password must be at least 8 characters long',
    74→      },
    75→    },
    76→  },
    77→  name: {
    78→    type: DataTypes.STRING(100),
    79→    allowNull: false,
    80→    validate: {
    81→      notNull: {
    82→        msg: 'Name is required',
    83→      },
    84→      notEmpty: {
    85→        msg: 'Name cannot be empty',
    86→      },
    87→      len: {
    88→        args: [2, 100],
    89→        msg: 'Name must be between 2 and 100 characters',
    90→      },
    91→    },
    92→  },
    93→  phone_number: {
    94→    type: DataTypes.STRING(20),
    95→    allowNull: true,
    96→    validate: {
    97→      isValidPhoneOrEmpty(value) {
    98→        if (value && value.trim() !== '') {
    99→          if (!/^\+?[1-9]\d{1,14}$/.test(value)) {
   100→            throw new Error('Phone number must be in E.164 format (e.g., +1234567890)');
   101→          }
   102→        }
   103→      },
   104→    },
   105→  },
   106→  is_active: {
   107→    type: DataTypes.BOOLEAN,
   108→    allowNull: false,
   109→    defaultValue: true,
   110→  },
   111→  refresh_token: {
   112→    type: DataTypes.STRING(512),
   113→    allowNull: true,
   114→  },
   115→  refresh_token_expires_at: {
   116→    type: DataTypes.DATE,
   117→    allowNull: true,
   118→  },
   119→}, {
   120→  tableName: 'users',
   121→  timestamps: true,
   122→  createdAt: 'created_at',
   123→  updatedAt: 'updated_at',
   124→  underscored: true,
   125→  indexes: [
   126→    {
   127→      name: 'idx_users_email',
   128→      unique: true,
   129→      fields: ['email'],
   130→    },
   131→    {
   132→      name: 'idx_users_role',
   133→      fields: ['role_id'],
   134→    },
   135→    {
   136→      name: 'idx_users_active',
   137→      fields: ['is_active'],
   138→    },
   139→    {
   140→      name: 'idx_users_refresh_token',
   141→      fields: ['refresh_token'],
   142→    },
   143→  ],
   144→  hooks: {
   145→    beforeCreate: async (user) => {
   146→      if (user.password) {
   147→        user.password_hash = await bcrypt.hash(user.password, 12);
   148→        user.password = undefined;
   149→      }
   150→    },
   151→    beforeUpdate: async (user) => {
   152→      if (user.changed('password') && user.password) {
   153→        user.password_hash = await bcrypt.hash(user.password, 12);
   154→        user.password = undefined;
   155→      }
   156→    },
   157→  },
   158→});
   159→
   160→User.prototype.clearRefreshToken = async function () {
   161→  this.refresh_token = null;
   162→  this.refresh_token_expires_at = null;
   163→  await this.save();
   164→};
   165→
   166→User.prototype.updateRefreshToken = async function (token, expiresAt) {
   167→  this.refresh_token = token;
   168→  this.refresh_token_expires_at = expiresAt;
   169→  await this.save();
   170→};
   171→
   172→User.prototype.isRefreshTokenValid = function () {
   173→  if (!this.refresh_token || !this.refresh_token_expires_at) {
   174→    return false;
   175→  }
   176→  return new Date() < new Date(this.refresh_token_expires_at);
   177→};
   178→
   179→User.prototype.comparePassword = async function (password) {
   180→  return await bcrypt.compare(password, this.password_hash);
   181→};
   182→
   183→export default User;
