     7→
     8→import { Router } from 'express';
     9→import PhoneLineAssignmentService from '../../../services/PhoneLineAssignmentService.js';
    10→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
    11→import { authorizeRole } from '../../../middleware/authorizeRole.js';
    12→import { AppError } from '../../../middleware/errorHandler.js';
    13→
    14→const router = Router();
    15→
    16→/**
    17→ * @route POST /api/v1/users/:userId/lines
    18→ * @desc Assign lines to a user (agent only)
    19→ * @access Admin only
    20→ */
    21→router.post('/:userId/lines', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
    22→  try {
    23→    const { userId } = req.params;
    24→    const { lineIds } = req.body;
    25→
    26→    if (!userId || isNaN(parseInt(userId))) {
    27→      throw new AppError('Invalid user ID', 400);
    28→    }
    29→
